        json: {
            ...item.json,
            rating: rating
        }
    });
}

newItems.sort((a, b) => b.json.rating - a.json.rating);

return newItems;

// 1. Берем ОДИН объект вакансии из источника через современный синтаксис
const freshVacancy = $("Code in JavaScript Deduplication").first().json;

